
(function(){'use strict';var config=window.WPCGSettings||{};var noticeTimer=null;var allowSelector='input, textarea, select, option, [contenteditable="true"], [data-wpcg-allow]';function domReady(callback){if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',callback,{once:!0});return}
callback()}
function closestElement(target,selector){if(!target){return null}
var element=target.nodeType===1?target:target.parentElement;if(!element||typeof element.closest!=='function'){return null}
return element.closest(selector)}
function isAllowedTarget(target){return Boolean(closestElement(target,allowSelector))}
function showNotice(){if(!config.showNotice||!config.noticeText||!document.body){return}
var notice=document.getElementById('wpcg-notice');if(!notice){notice=document.createElement('div');notice.id='wpcg-notice';notice.setAttribute('role','status');notice.setAttribute('aria-live','polite');document.body.appendChild(notice)}
notice.textContent=String(config.noticeText);notice.classList.add('wpcg-visible');window.clearTimeout(noticeTimer);noticeTimer=window.setTimeout(function(){notice.classList.remove('wpcg-visible')},1800)}
function blockEvent(event){if(isAllowedTarget(event.target)){return}
event.preventDefault();event.stopPropagation();showNotice()}
function disableImageDragging(){document.querySelectorAll('img:not([data-wpcg-allow])').forEach(function(image){image.setAttribute('draggable','false')})}
if(config.breakIframe){try{if(window.top!==window.self){window.top.location.href=window.self.location.href}}catch(error){}}
if(config.disableTextSelection){document.addEventListener('selectstart',blockEvent,{passive:!1,capture:!0})}
if(config.disableRightClick){document.addEventListener('contextmenu',blockEvent,{passive:!1,capture:!0})}
if(config.disableCopyCut){document.addEventListener('copy',blockEvent,{passive:!1,capture:!0});document.addEventListener('cut',blockEvent,{passive:!1,capture:!0})}
if(config.disableImageDrag){document.addEventListener('dragstart',function(event){var image=closestElement(event.target,'img');if(!image||image.matches('[data-wpcg-allow]')){return}
event.preventDefault();event.stopPropagation();showNotice()},{passive:!1,capture:!0});domReady(disableImageDragging)}
if(config.disableKeyboardShortcuts){document.addEventListener('keydown',function(event){if(isAllowedTarget(event.target)){return}
var key=String(event.key||'').toLowerCase();var modifier=event.ctrlKey||event.metaKey;var blocked=(modifier&&['a','c','s','p','u','x'].indexOf(key)!==-1)||key==='f12'||(event.ctrlKey&&event.shiftKey&&['i','j','c'].indexOf(key)!==-1);if(!blocked){return}
event.preventDefault();event.stopPropagation();showNotice()},{passive:!1,capture:!0})}
if(config.protectPrint){window.addEventListener('beforeprint',function(){if(document.body){document.body.classList.add('wpcg-print-protected')}});window.addEventListener('afterprint',function(){if(document.body){document.body.classList.remove('wpcg-print-protected')}})}})();


